// 多音字按上下文（教小鲤鱼 jiāo、稻上场 cháng、盛满 chéng、地 / 得 按用法），儿化的「儿」标 r（一点儿 yì diǎn r），
// 课本注成独立音节 ér 的照注 ér（诗句里的叶儿、苗儿）；单独一个字按它在识字表里的读音（重复的重 chóng、笼盖的笼 lǒng、磨坊的磨 mò）。
